def longest_dup_substring_length(s):
    n = len(s); B = 911382323; M = (1 << 61) - 1; a = [ord(c) for c in s]
    def has(L):
        if L == 0: return True
        h = 0; p = pow(B, L, M); seen = {}
        for i in range(n):
            h = (h * B + a[i]) % M
            if i >= L: h = (h - a[i - L] * p) % M
            if i >= L - 1:
                st = i - L + 1
                if h in seen and any(s[j:j + L] == s[st:st + L] for j in seen[h]): return True
                seen.setdefault(h, []).append(st)
        return False
    lo, hi = 0, n - 1
    while lo < hi:
        m = (lo + hi + 1) // 2
        if has(m): lo = m
        else: hi = m - 1
    return lo

