int longestDupSubstringLength(string s) {
    int n = s.size(); const unsigned long long B = 131;
    vector<unsigned long long> h(n + 1, 0), p(n + 1, 1); for (int i = 0; i < n; i++) { h[i+1] = h[i] * B + s[i]; p[i+1] = p[i] * B; }
    auto has = [&](int L) { if (!L) return true; unordered_map<unsigned long long, int> seen; seen.reserve(n * 2);
        for (int i = 0; i + L <= n; i++) { unsigned long long x = h[i+L] - h[i] * p[L]; auto it = seen.find(x); if (it != seen.end() && s.compare(it->second, L, s, i, L) == 0) return true; seen[x] = i; } return false; };
    int lo = 0, hi = n - 1; while (lo < hi) { int m = (lo + hi + 1) / 2; if (has(m)) lo = m; else hi = m - 1; } return lo;
}
